def apply_editorial(lessons):
    assert set(EDITS) == {l['id'] for l in lessons}, (set(EDITS) ^ {l['id'] for l in lessons})
    for lesson in lessons:
        edit = EDITS[lesson['id']]
        original = deepcopy(lesson['cards'])
        questions = deepcopy(edit['questions'])
        for n, question in enumerate(questions, 1):
            question['id'] = lesson['id'] + '.v5.q' + str(n)
        # Keep the useful explanation and its limit. Glossary dumps, duplicate summaries,
        # compulsory reveals and all old generated illustrations are removed.
        if edit['core']:
            teaching = [dict(title=t, text=s, kind='evidence') for t,s in edit['core']]
        elif any(c['title'] == 'Der Gedanke' for c in original):
            mechanism = next(c['text'] for c in original if c['title'] == 'Der Gedanke')
            boundary = next((c['text'] for c in original if c['title'] == 'Die entscheidende Grenze'), '')
            teaching = [dict(title='Was dahintersteckt', text=mechanism + ('\n\n' + boundary if boundary else ''), kind='evidence')]
        else:
            teaching = [dict(title='Was dahintersteckt', text='\n\n'.join(c['text'] for c in original if c['title'] != 'Im Alltag anwenden'), kind='evidence')]
        lesson['title'] = edit['title']
        lesson['cards'] = [dict(title=edit['title'], text=edit['scene'], kind='scene')] + teaching + [
            dict(title='Du entscheidest', text='Wende den Gedanken an.', kind='decision', probe=deepcopy(questions[0]))]
        lesson['questions'] = questions
        lesson['photo'] = None
        lesson.pop('visual', None)
        lesson['takeaway'] = questions[0]['explanation']
        lesson['objective'] = questions[-1]['explanation']
        lesson['mission'] = 'Erkläre den Kern an einem eigenen Beispiel und nenne eine Grenze.'
        lesson['reflection'] = lesson['mission']
    return lessons
